            "entry_points": [
              "P2P"
            ],
            "attacker_controlled": true,
            "bug_bounty_scope": "in-scope"
          },
          "test_procedure": "1. Send deeply nested branch nodes during sync. 2. Monitor memory allocation. 3. Check for stack overflow in recursive processing. 4. Test with all 16 children populated at each level. 5. Verify depth limits in sync implementation.",
          "bug_class": "Resource Exhaustion",
          "risk_category": "Denial of Service",
          "notes": "Source: PROP-0036, Trust Boundary: tb-004. Crashes prevent node from joining network."
