          "check_id": "W2B3:W2B3:CHK-0028",
          "property_id": "PROP-0037",
          "title": "Verify Trust Boundary Integrity: Are all Fusaka types handled explicitly in encode_node?",
          "severity": "High",
          "mindset": "Boundary Guard",
          "is_boundary_check": true,
          "reachability": {
            "classification": "external-reachable",
            "entry_points": [
              "Transaction"
            ],
            "attacker_controlled": true,
            "bug_bounty_scope": "in-scope"
          },
          "test_procedure": "1. Enumerate all Fusaka/Osaka types in state trie. 2. Verify isinstance checks are exhaustive. 3. Test each type reaches correct encoding path. 4. Submit transactions triggering each type. 5. Compare encoding with previous_trie.encode_node output.",
          "bug_class": "Type Dispatch",
          "risk_category": "Tampering",
          "notes": "Source: PROP-0037, Trust Boundary: tb-005. Wrong encoding path causes consensus splits."
        },
        "code_scope": {
          "locations": [],
          "resolution_status": "not_found",
